class Solution {
    public String convertToTitle(int columnNumber) {
        StringBuilder reversed = new StringBuilder();
        while (columnNumber > 0) {
            columnNumber--;
            reversed.append((char) ('A' + columnNumber % 26));
            columnNumber /= 26;
        }
        return reversed.reverse().toString();
    }
}

class Solution {
    public String convertToTitle(int columnNumber) {
        if (columnNumber == 0) {
            return "";
        }
        columnNumber--;
        return convertToTitle(columnNumber / 26) + (char) ('A' + columnNumber % 26);
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public String convertToTitle(int columnNumber) {
        Deque<Character> letters = new ArrayDeque<>();
        while (columnNumber > 0) {
            columnNumber--;
            letters.push((char) ('A' + columnNumber % 26));
            columnNumber /= 26;
        }

        StringBuilder result = new StringBuilder();
        while (!letters.isEmpty()) {
            result.append(letters.pop());
        }
        return result.toString();
    }
}

class Solution {
    public String convertToTitle(int columnNumber) {
        char[] buffer = new char[16];
        int write = buffer.length;
        while (columnNumber > 0) {
            columnNumber--;
            buffer[--write] = (char) ('A' + columnNumber % 26);
            columnNumber /= 26;
        }
        return new String(buffer, write, buffer.length - write);
    }
}

class Solution {
    public String convertToTitle(int columnNumber) {
        int length = 0;
        int copy = columnNumber;
        while (copy > 0) {
            copy--;
            copy /= 26;
            length++;
        }

        char[] answer = new char[length];
        int write = length - 1;
        while (columnNumber > 0) {
            columnNumber--;
            answer[write--] = (char) ('A' + columnNumber % 26);
            columnNumber /= 26;
        }
        return new String(answer);
    }
}
